import math

def calculate_area():
    print("Area Calculator")
    print("Supported shapes: circle, rectangle, triangle")
    shape = input("Enter the shape: ").strip().lower()

    try:
        if shape == "circle":
            radius = float(input("Enter the radius: "))
            if radius < 0:
                raise ValueError("Radius cannot be negative")
            area = math.pi * radius ** 2
        elif shape == "rectangle":
            length = float(input("Enter the length: "))
            width = float(input("Enter the width: "))
            if length < 0 or width < 0:
                raise ValueError("Dimensions cannot be negative")
            area = length * width
        elif shape == "triangle":
            base = float(input("Enter the base: "))
            height = float(input("Enter the height: "))
            if base < 0 or height < 0:
                raise ValueError("Dimensions cannot be negative")
            area = 0.5 * base * height
        else:
            print("Unsupported shape. Please choose circle, rectangle, or triangle.")
            return

        print(f"The area of the {shape} is: {area:.2f}")
    except ValueError as e:
        print(f"Invalid input: {e}")

if __name__ == "__main__":
    calculate_area()
```

This script prompts for a shape and its dimensions, then computes and displays the area (with basic input validation). You can extend it with more shapes as needed.
